package com.opensocket.aievent.core.issuetracking.change;
import java.util.Objects;
import com.opensocket.aievent.core.issuetracking.identity.ProviderExecutionAuthorizationRef;
public record ProviderRelationSyncCommand(String tenantId,String connectionId,String projectMappingId,String externalProjectId,String sourceExternalIssueId,String targetExternalIssueId,String relationType,String sourceMarker,String idempotencyKey,String correlationId,ProviderExecutionAuthorizationRef executionAuthorization) {
 public ProviderRelationSyncCommand(String tenantId,String connectionId,String projectMappingId,String externalProjectId,String sourceExternalIssueId,String targetExternalIssueId,String relationType,String sourceMarker,String idempotencyKey,String correlationId){this(tenantId,connectionId,projectMappingId,externalProjectId,sourceExternalIssueId,targetExternalIssueId,relationType,sourceMarker,idempotencyKey,correlationId,null);}
 public ProviderRelationSyncCommand { tenantId=req(tenantId,"tenantId");connectionId=req(connectionId,"connectionId");projectMappingId=req(projectMappingId,"projectMappingId");externalProjectId=norm(externalProjectId);sourceExternalIssueId=req(sourceExternalIssueId,"sourceExternalIssueId");targetExternalIssueId=req(targetExternalIssueId,"targetExternalIssueId");relationType=req(relationType,"relationType");sourceMarker=req(sourceMarker,"sourceMarker");idempotencyKey=req(idempotencyKey,"idempotencyKey");correlationId=norm(correlationId);if(executionAuthorization!=null&&!projectMappingId.equals(executionAuthorization.mappingId()))throw new IllegalArgumentException("executionAuthorization mappingId mismatch"); }
 private static String req(String v,String n){Objects.requireNonNull(v,n+" is required");String x=v.trim();if(x.isEmpty())throw new IllegalArgumentException(n+" is required");return x;} private static String norm(String v){return v==null?"":v.trim();}
}
